            SELECT COUNT(*) AS count
            FROM auditandcompliance ac WHERE CAST(ac.critfindnum AS REAL) / (ac.findtally + 1) > 0.5
            AND ac.remeddue < Date('now') AND ac.remedstate NOT IN ('Complete', 'Overdue');
