def test_case(pred_sqls, sol_sqls, db_name, conn):
    view_columns_sql = "SELECT name FROM pragma_table_info('whale_orders');"
    view_columns_result, _, _ = execute_queries(view_columns_sql, db_name, conn)
    view_columns = {row[0] for row in view_columns_result}
    expected_columns = {'orderspivot', 'recordvault', 'mktnote', 'dealcount', 'available_liquidity'}
    missing_columns = expected_columns - view_columns
    assert not missing_columns, (
        f"whale_orders view test failed: Missing columns {missing_columns}."
    )
    whale_condition_check_sql = "SELECT COUNT(*) FROM whale_orders WHERE dealcount <= (available_liquidity * 0.10);"
    condition_check_result, _, _ = execute_queries(whale_condition_check_sql, db_name, conn)
    failing_rows = condition_check_result[0][0]
    assert failing_rows == 0, (
        f"whale_orders view test failed: {failing_rows} rows do not satisfy the condition dealcount > available_liquidity * 0.10."
    )

